parameters.query:
WITH state AS (
  SELECT last_successful_sync_at FROM public.keycrm_sync_state WHERE sync_name='pipeline_cards_incremental'
)
SELECT COALESCE((SELECT last_successful_sync_at FROM state), now() - interval '1 hour') - interval '2 minutes' AS from_ts, now() AS to_ts;

parameters.jsCode:
const window = $('Load sync window').first().json;
const cards = new Map();
for (const item of items) {
  const pageCards = Array.isArray(item.json?.data) ? item.json.data : [];
  for (const card of pageCards) {
    const cardId = Number(card.id);
    const pipelineId = Number(card.pipeline_id);
    if (!Number.isInteger(cardId) || cardId < 1 || !Number.isInteger(pipelineId) || pipelineId < 1) continue;
    cards.set(cardId, {
      card_id: cardId,
      pipeline_id: pipelineId,
      source_id: Number.isInteger(Number(card.source_id)) ? Number(card.source_id) : null,
      manager_id: Number.isInteger(Number(card.manager_id)) ? Number(card.manager_id) : null,
      status_id: Number.isInteger(Number(card.status_id)) ? Number(card.status_id) : null,
      status_alias: typeof card.status?.alias === 'string' ? card.status.alias : null,
      status_title: typeof card.status?.title === 'string' ? card.status.title : null,
      status_is_final: typeof card.status?.is_final === 'boolean' ? card.status.is_final : null,
      is_finished: typeof card.is_finished === 'boolean' ? card.is_finished : null,
      closed_from: Number.isInteger(Number(card.closed_from)) ? Number(card.closed_from) : null,
      created_at: card.created_at || null,
      updated_at: card.updated_at || null,
      status_changed_at: card.status_changed_at || null,
      payments_total: Number.isFinite(Number(card.payments_total)) ? Number(card.payments_total) : 0,
      products_total: Number.isFinite(Number(card.products_total)) ? Number(card.products_total) : 0,
      utm_source: typeof card.utm_source === 'string' ? card.utm_source : null,
      utm_medium: typeof card.utm_medium === 'string' ? card.utm_medium : null,
      utm_campaign: typeof card.utm_campaign === 'string' ? card.utm_campaign : null
    });
  }
}
return [{json:{from_ts:window.from_ts,to_ts:window.to_ts,count:cards.size,cards:[...cards.values()]}}];
